WITH ss_joined AS (SELECT ss.ss_store_sk, s.s_store_name, ss.ss_sold_date_sk, ss.ss_net_paid_inc_tax, ss.ss_net_profit, ss.ss_ext_discount_amt, p.p_promo_id FROM store_sales ss JOIN store s ON ss.ss_store_sk = s.s_store_sk LEFT JOIN promotion p ON ss.ss_promo_sk = p.p_promo_sk), daily_agg AS (SELECT ss_store_sk, s_store_name, ss_sold_date_sk, SUM(ss_net_profit) AS daily_net_profit, SUM(ss_ext_discount_amt) AS daily_total_discount, COUNT(*) AS transaction_cnt FROM ss_joined GROUP BY ss_store_sk, s_store_name, ss_sold_date_sk), ranked AS (SELECT da.*, RANK() OVER (PARTITION BY da.ss_sold_date_sk ORDER BY da.transaction_cnt DESC) AS txn_rank, SUM(da.daily_total_discount) OVER (PARTITION BY da.ss_store_sk ORDER BY da.ss_sold_date_sk ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS future_discount FROM daily_agg da) SELECT ss_store_sk, s_store_name, ss_sold_date_sk, daily_net_profit, daily_total_discount, transaction_cnt, txn_rank, future_discount FROM ranked WHERE txn_rank <= 2 ORDER BY ss_sold_date_sk, txn_rank
